import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import '../appearance/presentation/appearance_controller.dart';
import '../appearance/domain/appearance_snapshot.dart';
import '../../core/widgets/sunya_glass.dart';
class AppearanceRecommendationsPage extends ConsumerWidget{const AppearanceRecommendationsPage({super.key});
@override Widget build(BuildContext context,WidgetRef ref){final items=ref.watch(appearanceProvider);final latest=items.isEmpty?null:items.first;final tips=<String>[];if(latest==null){tips.add('Create a controlled baseline photo before judging changes.');}else{tips.add('Keep photo conditions identical before comparing changes.');tips.add('Track hairline and density separately; a single selfie cannot establish the cause of thinning.');tips.add('Track beard coverage only as a visual trend, not as a medical measurement.');tips.add('Track under-eye appearance with consistent sleep, lighting and camera conditions.');tips.add('Use a simple skincare routine and log changes rather than changing several products at once.');}return Scaffold(appBar:AppBar(title:const Text('Appearance plan')),body:ListView(padding:const EdgeInsets.all(20),children:[Text('Your next actions',style:Theme.of(context).textTheme.displaySmall),const SizedBox(height:6),const Text('Recommendations are habit and tracking guidance. They are not a diagnosis.'),const SizedBox(height:20),...tips.map((x)=>Padding(padding:const EdgeInsets.only(bottom:10),child:SunyaGlassCard(padding:const EdgeInsets.all(16),child:Row(crossAxisAlignment:CrossAxisAlignment.start,children:[const Icon(Icons.check_circle_outline,color:Colors.orange),const SizedBox(width:12),Expanded(child:Text(x))])))),if(latest!=null&&latest.notes.isNotEmpty)Text('Latest note: '+latest.notes)]) ;}
}